j:jelly.g:evaluate:

        var title = jelly.jvar_cxs_result.title;
        title = GlideStringUtil.escapeHTML(title);
        var snippet = jelly.jvar_cxs_result.snippet;
        var index = jelly.jvar_cxs_index;

        var itemLinkTarget = JSUtil.notNil(jelly.jvar_cxs_result.link_target) ? jelly.jvar_cxs_result.link_target : "";
        var itemLink = "";
        if (jelly.jvar_cxs_result.link) {
            var url = new GlideURL(jelly.jvar_cxs_result.link);
            if (itemLinkTarget === "")
                url.set("sysparm_stack", "no");
            itemLink = url.toString();
        }

        var image = jelly.jvar_cxs_result.image.thumbnail.link;

        // this_helped : the action id will never change, this is used to show the checked pill if user clicked this helped
		var thisHelpedActionLabel = '';
		var thisHelpedActionValue = '';
		var thisHelpedActionActive = false;

		if(jelly.jvar_cxs_result.searchResultActions && jelly.jvar_cxs_result.searchResultActions.this_helped) {
			thisHelpedActionActive = true;
			var thisHelpedActionDetails = JSON.parse(jelly.jvar_cxs_result.searchResultActions.this_helped);
			thisHelpedActionLabel = thisHelpedActionDetails.actionLabel;
			thisHelpedActionValue = thisHelpedActionDetails.actionValue;
		}

        var is_doctype = jelly.jvar_cxs_doctype;
        var pill_button = '
';
        if (is_doctype != "true")
            pill_button ='
x'
